# illustrative (not in repo)
@registry.task("payment.charge")
async def charge(ctx: JobContext):
    p = ctx.payload
    async with ctx.sessionmaker() as s, s.begin():
        row = await upsert_pending(s, job_id=ctx.job.id, amount=p["amount"])   # unique job_id
        if row.status == "succeeded":
            return {"duplicate": True, "charge_id": row.charge_id}
    charge = await provider.charge(amount=p["amount"], idempotency_key=f"job:{ctx.job.id}")
    async with ctx.sessionmaker() as s, s.begin():
        await mark_succeeded(s, ctx.job.id, charge.id)
    return {"duplicate": False, "charge_id": charge.id}
